"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Fraction } from "@/components/ui/fraction"

type CheckboxProps = Omit<React.ComponentProps<"input">, "type"> & {
  /** The words are the control. */
  children: React.ReactNode
  /**
   * strike: checking strikes the words through, for things done.
   * stet: checking sets a row of dots under them, the proofreader's "let it stand", for things kept.
   * circled: checking rings them in one pen loop, as you circle a word on a page, for things chosen.
   */
  variant?: "strike" | "stet" | "circled"
  /** Classes for the label, which is the root. className goes to the input. */
  labelClassName?: string
  /** Pins a state for documentation ("hover", "focus"); set on the root. */
  "data-force"?: string
}

/** No box. The words are the control; checking marks them, by default striking them through in the accent. */
function Checkbox({ children, variant = "strike", className, labelClassName, "data-force": force, ...props }: CheckboxProps) {
  return (
    <label data-slot="checkbox" data-variant={variant} data-force={force} className={cn("db-check", labelClassName)}>
      <input type="checkbox" className={className} {...props} />
      <span>{children}</span>
      {variant === "circled" ? (
        <svg className="db-check-loop" viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true">
          {/* One hand loop: in at the upper left, round clockwise, and on past where it began. */}
          <path pathLength={1} d="M14 9C34 2 78 1 93 11C104 19 96 33 70 37C44 40 12 38 4 28C-3 19 14 8 40 5" />
        </svg>
      ) : null}
    </label>
  )
}

type CheckboxGroupProps = React.ComponentProps<"fieldset"> & {
  legend?: React.ReactNode
  /** Show how many are done, as a fraction under the list. */
  tally?: boolean
  /** What the tally says: done(count, total). */
  done?: (count: number, total: number) => React.ReactNode
}

const defaultDone = (count: number, total: number) => (count === total ? "done. Ready when you are." : "done")

/** A list of checkboxes under a small legend, with an optional tally whose figures turn like a counter's wheels. */
function CheckboxGroup({ legend, tally = false, done = defaultDone, className, children, onChange, ...props }: CheckboxGroupProps) {
  const set = React.useRef<HTMLFieldSetElement>(null)
  // null until the first count, so the fraction arrives with its figures and doesn't turn over on load.
  const [state, setState] = React.useState<{ count: number; total: number } | null>(null)

  const count = React.useCallback(() => {
    const boxes = [...(set.current?.querySelectorAll<HTMLInputElement>("input[type=checkbox]") ?? [])]
    setState({ count: boxes.filter((b) => b.checked).length, total: boxes.length })
  }, [])

  React.useEffect(count, [count])

  return (
    <>
      <fieldset
        ref={set}
        data-slot="checkbox-group"
        className={cn("db-checklist", className)}
        onChange={(e) => {
          onChange?.(e)
          if (tally) count()
        }}
        {...props}
      >
        {legend ? <legend className="db-label">{legend}</legend> : null}
        {children}
      </fieldset>
      {tally ? (
        <p data-slot="checkbox-tally" className="db-tally" aria-live="polite">
          {state ? (
            <>
              <Fraction count={state.count} total={state.total} />
              <span>{done(state.count, state.total)}</span>
            </>
          ) : null}
        </p>
      ) : null}
    </>
  )
}

export { Checkbox, CheckboxGroup, type CheckboxProps, type CheckboxGroupProps }

@layer components {
  /* ── db-check ── the words only; checking strikes them through */
  .db-check { position: relative; display: inline-block; cursor: pointer; color: var(--db-graphite); -webkit-tap-highlight-color: transparent; }
  .db-check > input { position: absolute; width: 1px; height: 1px; margin: 0; opacity: 0; pointer-events: none; }
  .db-check > span {
    --y: 60%;
    padding-inline: 0.18em; margin-inline: -0.18em; /* the pen runs past the words, as a hand does */
    background:
      linear-gradient(var(--db-accent), var(--db-accent)) no-repeat 100% var(--y) / 0% var(--db-stroke),
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 100% var(--y) / 0% var(--db-hairline);
    -webkit-box-decoration-break: clone; box-decoration-break: clone;
    transition:
      background-size var(--db-moderato) var(--db-breath),
      background-position 0s,
      color var(--db-moderato) var(--db-breath),
      font-weight var(--db-moderato) var(--db-breath);
  }
  .db-check:is(:hover, [data-force~="hover"]) > span { color: var(--db-ink); }
  /* Pointing sketches the strike in pencil; checking inks it. */
  .db-check:is(:hover, [data-force~="hover"]) > input:not(:checked, :disabled) + span { background-position: 100% var(--y), 0 var(--y); background-size: 0% var(--db-stroke), 100% var(--db-hairline); }
  .db-check > input:checked + span { background-position: 0 var(--y), 100% var(--y); background-size: 100% var(--db-stroke), 0% var(--db-hairline); color: var(--db-pencil); font-weight: 300; }
  .db-check:is([dir="rtl"], [dir="rtl"] *) > span { background-position: 0 var(--y), 0 var(--y); }
  .db-check:is([dir="rtl"], [dir="rtl"] *):is(:hover, [data-force~="hover"]) > input:not(:checked, :disabled) + span { background-position: 0 var(--y), 100% var(--y); }
  .db-check:is([dir="rtl"], [dir="rtl"] *) > input:checked + span { background-position: 100% var(--y), 0 var(--y); }
  .db-check > input:focus-visible + span,
  .db-check[data-force~="focus"] > span { outline: var(--db-stroke) solid var(--db-accent); outline-offset: 4px; }
  .db-check[data-force~="focus"] { outline: 0; }
  .db-check:has(input:disabled) { cursor: not-allowed; }
  .db-check > input:disabled + span { color: var(--db-pencil); opacity: 0.55; }

  .db-checklist { border: 0; margin: 0; padding: 0; display: grid; justify-items: start; gap: var(--db-space-3); font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-checklist > legend { padding: 0; margin-bottom: var(--db-space-4); }

  /* The tally: how many are done, as a fraction whose count rolls the way it moves. */
  .db-tally { display: flex; align-items: baseline; gap: var(--db-space-3); margin: var(--db-space-5) 0 0; font-size: var(--db-p); color: var(--db-pencil); }
  .db-tally > .db-fraction > .db-yours { display: inline-block; }

  /* ── stet and circled ── for things kept or chosen rather than done, where a strike would read as "no".
     Checked, the words are yours, so they turn italic; 1lh keeps the list's line so nothing below moves. */
  .db-check:is([data-variant="stet"], [data-variant="circled"]) > span { background: none; }
  .db-check:is([data-variant="stet"], [data-variant="circled"]) > input:checked + span {
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1lh; color: var(--db-ink);
  }
  /* Stet: the proofreader's "let it stand", a row of dots under the words. Pointing pencils the dots in; checking
     sets them down in the accent, a touch lower, with spiccato. */
  .db-check[data-variant="stet"] > span {
    text-decoration: underline dotted transparent; text-decoration-thickness: max(2px, 0.09em); text-underline-offset: 0.2em; text-decoration-skip-ink: none;
    transition: text-decoration-color var(--db-allegro) var(--db-exhale), text-underline-offset var(--db-moderato) var(--db-spiccato), color var(--db-moderato) var(--db-breath);
  }
  .db-check[data-variant="stet"]:is(:hover, [data-force~="hover"]) > input:not(:checked, :disabled) + span { text-decoration-color: var(--db-rule-strong); }
  .db-check[data-variant="stet"] > input:checked + span { text-decoration-color: var(--db-accent); text-underline-offset: 0.3em; }
  /* Circled: one pen loop round the words, the accent rings of the collage. It comes in at the upper left and runs on
     past where it began, as a hand never quite closes a circle. Pointing draws it in pencil; checking inks it. A loop
     has no heading to leave by, so it fades, then resets unseen. */
  .db-check-loop {
    position: absolute; left: calc(-7% - 0.4em); top: -0.44em; width: calc(114% + 0.8em); height: calc(100% + 0.84em); max-width: none; /* an ellipse must stand wider than the words to clear their corners */ overflow: visible; pointer-events: none;
    fill: none; stroke: var(--db-rule-strong); stroke-width: var(--db-hairline); stroke-linecap: round; stroke-dasharray: 1 1; stroke-dashoffset: 1; opacity: 0;
    transition: opacity var(--db-allegro) var(--db-breath), stroke-dashoffset 0s var(--db-allegro), stroke var(--db-allegro), stroke-width var(--db-allegro);
  }
  .db-check-loop > path { vector-effect: non-scaling-stroke; }
  .db-check:is([dir="rtl"], [dir="rtl"] *) > .db-check-loop { scale: -1 1; }
  .db-check:is(:hover, [data-force~="hover"]) > input:not(:checked, :disabled) ~ .db-check-loop,
  .db-check > input:checked ~ .db-check-loop { opacity: 1; stroke-dashoffset: 0; transition: opacity 0s, stroke-dashoffset var(--db-andante) var(--db-exhale), stroke var(--db-allegro), stroke-width var(--db-allegro); }
  .db-check > input:checked ~ .db-check-loop { stroke: var(--db-accent); stroke-width: var(--db-stroke); }
  .db-check > input:disabled ~ .db-check-loop { opacity: 0.35; }
  /* Forced colours drop background images, which draw the strike, and force the stet dots' transparent colour to
     text: restate both as plain text decoration, so checked and unchecked still differ. */
  @media (forced-colors: active) {
    .db-check:not([data-variant="stet"], [data-variant="circled"]) > input:checked + span { text-decoration: line-through; }
    .db-check[data-variant="stet"] > span { text-decoration-line: none; }
    .db-check[data-variant="stet"] > input:checked + span { text-decoration-line: underline; }
    .db-check-loop { stroke: CanvasText; }
    .db-check > input:checked ~ .db-check-loop { stroke: Highlight; }
  }
}
